import {
  Button,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  type SelectChangeEvent,
  TextField,
  styled
} from '@mui/material'

import CLUB_BELONGING from 'src/data/belonging'
import { CATEGORY_MAIN, CATEGORY_MAP } from 'src/data/categories'

import type { ClubInformationRequestData } from 'src/hooks/api/settings'

interface ClubSettings {
  clubInformation: ClubInformationRequestData & { name?: string }
  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void
  handleSelect: (e: SelectChangeEvent<string>) => void
  handleClickEditButton: React.MouseEventHandler<HTMLButtonElement>
  fixedClubName?: string
}

const ClubSettingsField: React.FC<ClubSettings> = ({
  clubInformation,
  handleChange,
  handleSelect,
  handleClickEditButton,
  fixedClubName
}) => {
  return (
    <Grid container alignItems="center" mt={2} spacing={2}>
      <ItemGrid item xs={12} sm={6}>
        <TextField
          fullWidth
          label={fixedClubName ? '동아리명은 수정할 수 없습니다' : '동아리명'}
          name="name"
          id="name"
          value={clubInformation.name ?? fixedClubName ?? ''}
          disabled={!!fixedClubName}
          onChange={handleChange}
        />
      </ItemGrid>
      <ItemGrid item xs={12} sm={6}>
        <TextField
          label="동아리 설명"
          required
          name="description"
          id="description"
          fullWidth
          value={clubInformation.description}
          onChange={handleChange}
        />
      </ItemGrid>

      <ItemGrid item xs={12} sm={6}>
        <TextField
          label="동아리 장소"
          name="location"
          id="location"
          fullWidth
          value={clubInformation.location}
          onChange={handleChange}
        />
      </ItemGrid>
      <ItemGrid item xs={6}>
        <FormControl fullWidth>
          <InputLabel id="belonging-label">소속</InputLabel>
          <Select
            labelId="belonging-label"
            id="belonging"
            name="belonging"
            label="소속"
            value={clubInformation.belonging}
            onChange={handleSelect}
            required
          >
            {CLUB_BELONGING &&
              CLUB_BELONGING.map((name, idx) => (
                <MenuItem key={idx} value={name}>
                  {name}
                </MenuItem>
              ))}
          </Select>
        </FormControl>
      </ItemGrid>
      <ItemGrid item xs={6}>
        <FormControl fullWidth>
          <InputLabel id="category-label">동아리 대분류</InputLabel>
          <Select
            labelId="category-label"
            id="category"
            name="categoryMain"
            label="대분류"
            value={clubInformation.categoryMain}
            onChange={handleSelect}
            required
          >
            {Object.values(CATEGORY_MAIN).map((name, idx) => (
              <MenuItem key={idx} value={name}>
                {name}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </ItemGrid>
      <ItemGrid item xs={6}>
        <FormControl fullWidth>
          <InputLabel id="category-label">동아리 소분류</InputLabel>
          <Select
            labelId="category-label"
            id="categorySub"
            name="categorySub"
            label="소분류"
            value={clubInformation.categorySub ?? ''}
            onChange={handleSelect}
          >
            {CATEGORY_MAP[clubInformation.categoryMain]?.map((name, idx) => (
              <MenuItem key={idx} value={name}>
                {name}
              </MenuItem>
            ))}
            <MenuItem key={'none'} value="">
              없음
            </MenuItem>
          </Select>
        </FormControl>
      </ItemGrid>
      <ItemGrid item xs={12} justifyContent={'flex-end'}>
        <Button variant="contained" color="success" onClick={handleClickEditButton}>
          {fixedClubName ? '수정 / 등록' : '등록'}
        </Button>
      </ItemGrid>
    </Grid>
  )
}

export default ClubSettingsField

const ItemGrid = styled(Grid)({
  display: 'flex'
})
